  s.innerHTML+='<p>Set these while parked. Home, Work and custom coordinates stay on this device.</p><form>'+field('driverName','Dispatch name',state.driverName||readProfile().name,'text')+'<label>Objective<select name="mode">'+D.MODES.map(m=>'<option '+(m===state.mode?'selected':'')+'>'+m+'</option>').join('')+'</select>'+ '</label><label>Goal type<select name="goalKind"><option value="revenue">Revenue</option><option value="net">Net profit</option></select></label><label>Goal period<select name="goalPeriod"><option value="day">Today</option><option value="week">This week</option></select></label>'+field('goalAmount','Target ($)',state.goal?.amount)+field('deadline','Home / goal deadline',state.goal?.deadline?new Date(Date.parse(state.goal.deadline)-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16):'','datetime-local')+field('minimumHourly','Minimum net $/hour',state.minimumHourly)+field('maxDistance','Maximum miles from base',state.maxDistance)+field('maxShiftHours','Maximum shift hours',state.maxShiftHours)+field('minimumMile','Minimum net $/mile',state.minimumMile)+field('acceptanceTarget','Diamond acceptance target (%)',state.acceptanceTarget)+'<label>Base type<select name="baseType"><option>HOME</option><option>WORK</option><option>CUSTOM DESTINATION</option></select></label>'+field('baseLat','Private base latitude',destination.coords?.[0])+field('baseLon','Private base longitude',destination.coords?.[1])+field('model','Vehicle',v.model||'','text')+field('fuelCostPerMile','Actual fuel $/mile',v.fuelCostPerMile)+field('reservePerMile','Maintenance + replacement $/mile',v.reservePerMile)+field('mpg','Actual MPG',v.mpg)+field('odometer','Odometer miles',v.odometer)+'<label class="wide"><span><input type="checkbox" name="diamond" '+(state.diamond?'checked':'')+'> Preserve Uber acceptance across modes</span></label><label class="wide"><span><input type="checkbox" name="paidRepositioning" '+(state.paidRepositioning!==false?'checked':'')+'> Prefer paid repositioning</span></label><label class="wide"><span><input type="checkbox" name="radioCue" '+(state.radioCue?'checked':'')+'> Subtle dispatcher cue</span></label><label class="wide"><span><input type="checkbox" name="aiUnderstanding" '+(state.aiUnderstanding?'checked':'')+'> Enable optional cloud language understanding (sends spoken requests)</span></label><button class="wide">Save Copilot settings</button></form><div class="dispatch-controls"><button id="copilotGps">Start foreground GPS</button><button id="copilotVoiceOn">Enable spoken advice</button><button id="copilotVoiceOff">Silence + stop microphone</button><button id="copilotPrivateClear">Clear private destination</button></div><p id="dispatchSaveStatus" role="status"></p><p>Vehicle audio follows your phone’s Bluetooth output. Browser voice support varies; there is no background wake word or Siri App Intent in this PWA.</p>';
  s.insertAdjacentHTML('beforeend','<details><summary>Fuel, maintenance & vehicle records</summary><p>Actual purchases stay separate from estimated reserves. Fuel consumed per mile requires mileage coverage; purchase amounts alone are not MPG.</p><form id="dispatchVehicleLog"><label>Record type<select name="type"><option>fuel</option><option>maintenance</option><option>tires</option><option>brakes</option><option>repair</option><option>charging</option><option>parking</option></select></label><label>Amount ($)<input name="amount" type="number" min="0" step="any" required></label><label>Odometer<input name="odometer" type="number" min="0" required></label><label>Date<input name="date" type="date" required></label><label>Gallons / kWh (optional)<input name="quantity" type="number" min="0" step="any"></label><button>Save vehicle record</button></form><div id="dispatchVehicleHistory"></div></details><details><summary>Vehicle replacement comparison</summary><p>Enter your own assumptions. This compares operating cost only, before acquisition, financing and resale value.</p><form id="dispatchVehicleCompare"><label>Total miles per week<input name="miles" type="number" min="0" required></label><label>Replacement fuel / charging $/mile<input name="energy" type="number" min="0" step="any" required></label><label>Replacement reserve $/mile<input name="reserve" type="number" min="0" step="any" required></label><button>Compare weekly costs</button></form><p id="dispatchVehicleComparison"></p></details>');
  const availability=document.createElement('fieldset');availability.className='wide';availability.innerHTML='<legend>Apps available to me · verify local eligibility</legend>'+['Uber','Empower','Lyft'].map(p=>'<label><input type="checkbox" name="availablePlatform" value="'+p+'" '+((state.platforms||currentApps.map(a=>a.name)).includes(p)?'checked':'')+'> '+p+'</label>').join('');s.querySelector('form button').before(availability);
  const voiceField=document.createElement('label');voiceField.className='wide';voiceField.innerHTML='Dispatcher voice<select name="dispatcherVoice" id="dispatcherVoice"></select><span id="dispatcherVoiceStatus" role="status"></span>';s.querySelector('form button').before(voiceField);
  const populateVoices=()=>{if(!s.isConnected)return;const select=s.querySelector('#dispatcherVoice'),saved=select.dataset.loaded?select.value:state.voiceURI||'',voices=HomeBaseVoice.englishVoices(window.speechSynthesis?.getVoices()||[]),chosen=HomeBaseVoice.selectVoice(voices,saved);select.innerHTML='<option value="">Dispatcher · automatic</option>'+voices.map(v=>'<option value="'+esc(v.voiceURI)+'">'+esc(v.name)+' · '+esc(v.lang)+'</option>').join('');if(saved&&!voices.some(v=>v.voiceURI===saved)){const option=document.createElement('option');option.value=saved;option.textContent='Saved voice unavailable · automatic fallback';select.append(option);}select.value=saved;select.dataset.loaded='true';s.querySelector('#dispatcherVoiceStatus').textContent=chosen?'Using '+chosen.name+' with measured pacing and lower pitch.':'Device voices not listed yet. Dispatcher pacing uses the phone default.';};populateVoices();window.speechSynthesis?.addEventListener?.('voiceschanged',populateVoices);const voiceObserver=new MutationObserver(()=>{if(!s.isConnected){window.speechSynthesis?.removeEventListener?.('voiceschanged',populateVoices);voiceObserver.disconnect();}});voiceObserver.observe(workspaceContent,{childList:true});s.querySelector('#dispatcherVoice').onchange=()=>{state.voiceURI=s.querySelector('#dispatcherVoice').value;save();populateVoices();};
  const preview=document.createElement('button');preview.id='previewDispatcher';preview.type='button';preview.textContent='Preview dispatcher';s.querySelector('.dispatch-controls').prepend(preview);preview.onclick=()=>{if(moving)return;voiceEnabled=true;quietUntil=0;say('Standing by. Tell me the objective.',{address:true});};
  const voiceHelp=document.createElement('p');voiceHelp.textContent='Dispatcher delivery uses your available phone voices. Choose a voice and preview it while parked. Selection stays on this device.';voiceField.after(voiceHelp);
  const renderVehicle=()=>{s.querySelector('#dispatchVehicleHistory').innerHTML=(state.vehicle?.logs||[]).slice(-10).reverse().map(r=>'<p>'+esc(r.date)+' · '+esc(r.type)+' · '+money(r.amount)+' · odometer '+r.odometer+'</p>').join('');};renderVehicle();
  s.querySelector('#dispatchVehicleLog').onsubmit=e=>{e.preventDefault();if(moving)return;const f=new FormData(e.target),row={id:crypto.randomUUID(),type:f.get('type'),amount:Number(f.get('amount')),odometer:Number(f.get('odometer')),date:f.get('date'),quantity:f.get('quantity')===''?null:Number(f.get('quantity')),source:'USER-REPORTED'};state.vehicle={...state.vehicle,odometer:row.odometer,logs:[...(state.vehicle?.logs||[]),row].slice(-500)};save();renderVehicle();e.target.reset();};
  s.querySelector('#dispatchVehicleCompare').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),old=D.vehicleCost({miles:Number(f.get('miles')),fuelCostPerMile:state.vehicle?.fuelCostPerMile,reservePerMile:state.vehicle?.reservePerMile}),replacement=D.vehicleCost({miles:Number(f.get('miles')),fuelCostPerMile:Number(f.get('energy')),reservePerMile:Number(f.get('reserve'))});s.querySelector('#dispatchVehicleComparison').textContent=old!==null?'Current '+money(old)+' / week; replacement '+money(replacement)+' / week; modeled difference '+money(old-replacement)+'.':'Enter current vehicle costs first.';};
  const form=s.querySelector('form');form.elements.baseLat.min='-90';form.elements.baseLon.min='-180';form.elements.goalKind.value=state.goal?.kind||'revenue';form.elements.goalPeriod.value=state.goal?.period||'day';form.elements.baseType.value=destination.type||'HOME';
  form.onsubmit=e=>{e.preventDefault();try{const f=new FormData(form),n=k=>f.get(k)===''?null:Number(f.get(k));state.driverName=String(f.get('driverName'));state.mode=String(f.get('mode'));state.goal={kind:f.get('goalKind'),period:f.get('goalPeriod'),amount:n('goalAmount'),deadline:f.get('deadline')?new Date(f.get('deadline')).toISOString():null};for(const key of ['minimumHourly','maxDistance','maxShiftHours','minimumMile','acceptanceTarget'])state[key]=n(key);state.vehicle={...state.vehicle,model:String(f.get('model')),fuelCostPerMile:n('fuelCostPerMile'),reservePerMile:n('reservePerMile'),mpg:n('mpg'),odometer:n('odometer')};state.diamond=f.has('diamond');state.paidRepositioning=f.has('paidRepositioning');state.costPerMile=state.vehicle.fuelCostPerMile!==null&&state.vehicle.reservePerMile!==null?state.vehicle.fuelCostPerMile+state.vehicle.reservePerMile:null;state.platforms=f.getAll('availablePlatform');state.radioCue=f.has('radioCue');state.aiUnderstanding=f.has('aiUnderstanding');const lat=n('baseLat'),lon=n('baseLon');if(lat!==null&&lon!==null){if(Math.abs(lat)>90||Math.abs(lon)>180)throw Error('Invalid destination coordinates.');state.destination=[lat,lon];write('homeBasePrivateDestination',{type:f.get('baseType'),coords:state.destination});}save();update(true);s.querySelector('#dispatchSaveStatus').textContent='Saved on this device.';}catch(e){s.querySelector('#dispatchSaveStatus').textContent=e.message;}};
  s.querySelector('#copilotGps').onclick=enableGps;s.querySelector('#copilotVoiceOn').onclick=()=>{voiceEnabled=true;say('Standing by. Tap Talk when you are ready.',{address:true});};s.querySelector('#copilotVoiceOff').onclick=()=>{voiceEnabled=false;cancelSpeech();recognition?.abort();q('#copilotStatus').textContent='Voice off · microphone stopped';};s.querySelector('#copilotPrivateClear').onclick=()=>{state.destination=null;localStorage.removeItem('homeBasePrivateDestination');attachRefresh();};
