  const economics=document.createElement('details');economics.innerHTML='<summary>Wait versus reposition economics</summary><p>Enter observed or estimated inputs while parked. No fixed eight-minute timer is assumed.</p><form>'+['hourlyRate','waitMinutes','moveMinutes','moveCost','nextZoneHourlyRate','expectedWaitBenefit'].map(k=>'<label>'+k+'<input name="'+k+'" type="number" '+(k==='net'?'':'min="0"')+' step="any" required></label>').join('')+'<button>Calculate wait threshold</button></form><p role="status"></p>';s.append(economics);economics.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),inputs=Object.fromEntries([...f].map(([k,v])=>[k,Number(v)])),result=D.opportunity(inputs);state.opportunity=inputs;state.waitStartedAt=new Date(Date.now()-inputs.waitMinutes*60000).toISOString();save();economics.querySelector('p[role]').textContent='Wait cost '+money(result.wait_cost)+'; move cost including time '+money(result.reposition_cost)+'; modeled wait limit '+(result.wait_threshold_minutes?.toFixed(1)||'unknown')+' minutes. Inputs are driver-reported assumptions.';update(true);};
